24	type object struct {
25		cid    string
26		size   int
27		chunks [][]byte // raw chunk bytes, in reconstruction order
28		cids   []string // chunk identifiers, parallel to chunks
29	}
30	
31	// pin records a retention guarantee for one object. A nil expiresAt means
32	// the object is retained permanently; otherwise the pin is in force until
33	// the given instant. Pins live in process memory only and are not preserved
34	// across restarts.
35	type pin struct {
36		expiresAt *time.Time
37	}
38	
39	// validPin reports whether p is in force at now. Expired pins are
40	// equivalent to no pin at all.
41	func validPin(p pin, now time.Time) bool {
42		return p.expiresAt == nil || p.expiresAt.After(now)
43	}
44	
45	// blockRef holds one unique stored block. refs counts the live objects that
46	// reference the block; a block repeated within one object still counts once.
47	type blockRef struct {
48		data []byte
49		refs int
50	}
51	
52	// store is an in-process content-addressed object store. Objects are
53	// immutable once inserted; inserts and deletes happen under the write lock
54	// so readers never observe a partially written object. Blocks are stored
55	// once and shared by every object that references them; a block is dropped
56	// as soon as no live object references it.
57	type store struct {
58		mu      sync.RWMutex
59		objects map[string]*object
60		blocks  map[string]*blockRef
61		pins    map[string]pin
62	}
63	
64	func newStore() *store {
65		return &store{
66			objects: make(map[string]*object),
67			blocks:  make(map[string]*blockRef),
68			pins:    make(map[string]pin),
69		}
70	}
71	
72	// chunkCID returns the identifier for one chunk's raw bytes.
73	func chunkCID(data []byte) string {
74		sum := sha256.Sum256(data)
75		return cidPrefix + hex.EncodeToString(sum[:])
76	}
77	
78	// rootCID derives the object identifier from the deterministic manifest: the
79	// total object length followed by the ordered chunk identifiers, encoded as
80	// "size:<N>\n" then one "<cid>\n" line per chunk.
81	func rootCID(size int, cids []string) string {
82		var b strings.Builder
83		fmt.Fprintf(&b, "size:%d\n", size)
84		for _, c := range cids {
85			b.WriteString(c)
86			b.WriteByte('\n')
87		}
88		sum := sha256.Sum256([]byte(b.String()))
89		return cidPrefix + hex.EncodeToString(sum[:])
90	}
91	
92	// put stores the object, or returns the existing one when the same root
93	// identifier is already present. Exactly one concurrent caller observes
94	// created == true for a given object. Newly stored objects register their
95	// unique chunks in the shared block table; repeated chunks within the
96	// object and chunks shared with other objects are stored only once.
97	func (s *store) put(obj *object) (stored *object, created bool) {
98		s.mu.Lock()
99		defer s.mu.Unlock()
100		if existing, ok := s.objects[obj.cid]; ok {
101			return existing, false
102		}
103		s.objects[obj.cid] = obj
104		seen := make(map[string]bool, len(obj.cids))
105		for i, c := range obj.cids {
106			if b, ok := s.blocks[c]; ok {
107				obj.chunks[i] = b.data // share the stored copy
108				if !seen[c] {
109					b.refs++
110				}
111			} else {
112				s.blocks[c] = &blockRef{data: obj.chunks[i], refs: 1}
113			}
114			seen[c] = true
115		}
116		return obj, true
117	}
118	
119	// get returns the object for a root identifier, or nil when absent.
120	func (s *store) get(cid string) *object {
121		s.mu.RLock()
122		defer s.mu.RUnlock()
123		return s.objects[cid]
124	}
125	
126	// getBlock returns the raw bytes of a stored block, or nil when no live
127	// object references it.
128	func (s *store) getBlock(cid string) []byte {
129		s.mu.RLock()
130		defer s.mu.RUnlock()
131		if b, ok := s.blocks[cid]; ok {
132			return b.data
133		}
134		return nil
135	}
136	
137	// storageStats is a consistent snapshot of the store's occupancy.
138	type storageStats struct {
139		objects      int
140		logicalBytes int
141		blocks       int
142		storedBytes  int
143	}
144	
145	// stats snapshots object and deduplicated block occupancy under one lock
146	// hold, so the four counters always describe the same instant.
147	func (s *store) stats() storageStats {
148		s.mu.RLock()
149		defer s.mu.RUnlock()
150		st := storageStats{objects: len(s.objects), blocks: len(s.blocks)}
151		for _, obj := range s.objects {
152			st.logicalBytes += obj.size
153		}
154		for _, b := range s.blocks {
155			st.storedBytes += len(b.data)
156		}
157		return st
158	}
159	
160	// setPin pins cid with the given expiration, replacing any previous pin. It
161	// reports ok == false when the object does not exist. created is true when
162	// no valid pin was in force at now. The check and the update are atomic
163	// with respect to garbage collection.
164	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
165		s.mu.Lock()
166		defer s.mu.Unlock()
167		if _, exists := s.objects[cid]; !exists {
168			return false, false
169		}
170		existing, found := s.pins[cid]
171		created = !found || !validPin(existing, now)
172		s.pins[cid] = pin{expiresAt: expiresAt}
173		return created, true
174	}
175	
176	// removePin deletes the pin for cid, reporting whether a valid pin was in
177	// force at now. Expired pins are removed lazily and reported as absent.
178	func (s *store) removePin(cid string, now time.Time) bool {
179		s.mu.Lock()
180		defer s.mu.Unlock()
181		p, found := s.pins[cid]
182		if !found || !validPin(p, now) {
183			delete(s.pins, cid)
184			return false
185		}
186		delete(s.pins, cid)
187		return true
188	}
189	
190	// pinEntry is one live pin in a listing.
191	type pinEntry struct {
192		cid       string
193		expiresAt *time.Time
194	}
195	
