1	package server
2	
3	import (
4		"bytes"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"io"
9		"mime"
10		"net/http"
11		"sort"
12		"strconv"
13	)
14	
15	// bundleMediaType is the only media type accepted and produced by the
16	// bundle endpoints.
17	const bundleMediaType = "application/vnd.cidvault.bundle+json"
18	
19	// bundleVersion is the only bundle format version this server understands.
20	const bundleVersion = 1
21	
22	// maxBundleSize bounds the wire size of an import body. A bundle carrying a
23	// maximum-size object is dominated by the Base64 expansion of its blocks;
24	// the slack covers JSON framing, identifiers and whitespace.
25	const maxBundleSize = 4*(MaxObjectSize/3+1) + 1<<20
26	
27	// bundleRoot mirrors the manifest of the exported object.
28	type bundleRoot struct {
29		CID       string   `json:"cid"`
30		Size      int      `json:"size"`
31		ChunkSize int      `json:"chunkSize"`
32		Chunks    []string `json:"chunks"`
33	}
34	
35	// bundleBlock carries one unique block with its raw bytes in standard
36	// RFC 4648 Base64.
37	type bundleBlock struct {
38		CID  string `json:"cid"`
39		Data string `json:"data"`
40	}
41	
42	// bundleDocument is the JSON body of GET /v1/bundles/{cid}.
43	type bundleDocument struct {
44		Version int           `json:"version"`
45		Root    bundleRoot    `json:"root"`
46		Blocks  []bundleBlock `json:"blocks"`
47	}
48	
49	// getBundle handles GET /v1/bundles/{cid}.
50	func (s *store) getBundle(w http.ResponseWriter, r *http.Request) {
51		if r.Method != http.MethodGet {
52			w.Header().Set("Allow", http.MethodGet)
53			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
54			return
55		}
56		obj := s.lookupObject(w, r)
57		if obj == nil {
58			return
59		}
60		dataByCID := make(map[string][]byte, len(obj.cids))
61		for i, c := range obj.cids {
62			dataByCID[c] = obj.chunks[i]
63		}
64		cids := make([]string, 0, len(dataByCID))
65		for c := range dataByCID {
66			cids = append(cids, c)
67		}
68		sort.Strings(cids)
69		blocks := make([]bundleBlock, 0, len(cids))
70		for _, c := range cids {
71			blocks = append(blocks, bundleBlock{
72				CID:  c,
73				Data: base64.StdEncoding.EncodeToString(dataByCID[c]),
74			})
75		}
76		w.Header().Set("Content-Type", bundleMediaType)
77		_ = json.NewEncoder(w).Encode(bundleDocument{
78			Version: bundleVersion,
79			Root: bundleRoot{
80				CID:       obj.cid,
81				Size:      obj.size,
82				ChunkSize: ChunkSize,
83				Chunks:    obj.cids,
84			},
85			Blocks: blocks,
86		})
87	}
88	
89	// bundleRootJSON is the strictly decoded root section of an import body.
90	// Pointer fields distinguish a missing key from a zero value; numbers stay
91	// raw so quoted strings are rejected as type errors.
92	type bundleRootJSON struct {
93		CID       *string          `json:"cid"`
94		Size      *json.RawMessage `json:"size"`
95		ChunkSize *json.RawMessage `json:"chunkSize"`
96		Chunks    *[]string        `json:"chunks"`
97	}
98	
99	// bundleBlockJSON is one strictly decoded block entry of an import body.
100	type bundleBlockJSON struct {
101		CID  *string `json:"cid"`
102		Data *string `json:"data"`
103	}
104	
105	// bundleJSON is the strictly decoded import body.
106	type bundleJSON struct {
107		Version *json.RawMessage   `json:"version"`
108		Root    *bundleRootJSON    `json:"root"`
109		Blocks  *[]bundleBlockJSON `json:"blocks"`
110	}
111	
112	// postBundle handles POST /v1/bundles.
113	func (s *store) postBundle(w http.ResponseWriter, r *http.Request) {
114		if r.Method != http.MethodPost {
115			w.Header().Set("Allow", http.MethodPost)
116			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
117			return
118		}
119		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
120		if err != nil || mediaType != bundleMediaType {
121			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
122			return
123		}
124		body, err := io.ReadAll(io.LimitReader(r.Body, maxBundleSize+1))
125		if err != nil {
126			writeError(w, http.StatusBadRequest, "invalid_bundle")
127			return
128		}
129		if len(body) > maxBundleSize {
130			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
131			return
132		}
133		obj, code, status := parseBundle(body)
134		if code != "" {
135			writeError(w, status, code)
136			return
137		}
138		stored, created := s.put(obj)
139		respStatus := http.StatusOK
140		if created {
141			respStatus = http.StatusCreated
142		}
143		writeJSON(w, respStatus, objectResponse{
144			CID:       stored.cid,
145			Size:      stored.size,
146			ChunkSize: ChunkSize,
147			Chunks:    stored.cids,
148			Created:   created,
149		})
150	}
151	
152	// parseBundle fully validates a bundle body and, on success, returns the
153	// object ready to store. On failure it returns the error code and HTTP
154	// status to report; the store is never touched on the failure path.
155	func parseBundle(body []byte) (obj *object, code string, status int) {
156		invalid := func() (*object, string, int) {
157			return nil, "invalid_bundle", http.StatusBadRequest
158		}
159		integrity := func() (*object, string, int) {
160			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
161		}
162	
163		if !wellFormedJSON(body) {
164			return invalid()
165		}
166		var doc bundleJSON
167		dec := json.NewDecoder(bytes.NewReader(body))
168		dec.DisallowUnknownFields()
169		if err := dec.Decode(&doc); err != nil {
170			return invalid()
171		}
172		if doc.Version == nil || doc.Root == nil || doc.Blocks == nil ||
173			doc.Root.CID == nil || doc.Root.Size == nil || doc.Root.ChunkSize == nil ||
174			doc.Root.Chunks == nil {
175			return invalid()
176		}
177		for _, b := range *doc.Blocks {
178			if b.CID == nil || b.Data == nil {
179				return invalid()
180			}
181		}
182	
183		// Numeric fields must be integers. An integer outside int64 range is a
