249		if version != bundleVersion || chunkSize != ChunkSize {
250			return nil, "unsupported_delta_bundle", http.StatusUnprocessableEntity
251		}
252		if size > MaxObjectSize {
253			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
254		}
255		if size < 0 {
256			return integrity()
257		}
258	
259		// Carried blocks must be a subset of the unique referenced identifiers:
260		// no duplicates and nothing the manifest does not reference. Missing
261		// blocks are expected in an incremental bundle and come from the store.
262		referenced := make(map[string]bool, len(*doc.Root.Chunks))
263		for _, c := range *doc.Root.Chunks {
264			referenced[c] = true
265		}
266		seen := make(map[string]bool, len(*doc.Blocks))
267		for _, b := range *doc.Blocks {
268			if seen[*b.CID] || !referenced[*b.CID] {
269				return integrity()
270			}
271			seen[*b.CID] = true
272		}
273	
274		// Every carried block identifier must be the digest of its decoded bytes.
275		for cid, data := range blockData {
276			if chunkCID(data) != cid {
277				return integrity()
278			}
279		}
280	
281		cids := *doc.Root.Chunks
282		if (size == 0) != (len(cids) == 0) {
283			return integrity()
284		}
285		return &deltaContent{
286			cid:    *doc.Root.CID,
287			size:   size,
288			cids:   append([]string{}, cids...),
289			blocks: blockData,
290		}, "", 0
291	}
292	
293	// assembleDelta merges the carried blocks with blocks still referenced by
294	// local objects, then applies the same fixed chunking, length and root
295	// checks as a full-bundle import. A referenced block held nowhere yields
296	// missing_block. The store itself is not mutated here; put happens only once
297	// the returned object is fully validated.
298	func (s *store) assembleDelta(content *deltaContent) (*object, string, int) {
299		chunks := make([][]byte, len(content.cids))
300		for i, c := range content.cids {
301			if data, ok := content.blocks[c]; ok {
