// auditLog is the process-local audit event stream. Events are appended
// after the business state commits, under the same lock that committed the
// change, so concurrent events observe commit order. The log is not
// retained across restarts.
type auditLog struct {
	mu      sync.Mutex
	events  []auditEvent // ascending seq, oldest first
	nextSeq int64
}

func newAuditLog() *auditLog {
	return &auditLog{nextSeq: 1}
}

// append stamps and records one event, evicting the oldest events beyond the
// retention capacity. Sequence numbers keep increasing across evictions.
func (l *auditLog) append(e auditEvent) {
	l.mu.Lock()
	defer l.mu.Unlock()
	e.Seq = l.nextSeq
	l.nextSeq++
	e.At = time.Now().UTC()
	l.events = append(l.events, e)
	if len(l.events) > auditCapacity {
		excess := len(l.events) - auditCapacity
		l.events = append(l.events[:0], l.events[excess:]...)
	}
}
