			return
		}
		v, err := strconv.ParseInt(values[0], 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
		after = v
	}
	limit := 100
	if values, present := query["limit"]; present {
		if len(values) != 1 {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
		v, err := strconv.ParseInt(values[0], 10, 64)
		if err != nil || v < 1 || v > 1000 {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
