// force at now. Expired pins are removed lazily and reported as absent.
func (s *store) removePin(cid string, now time.Time) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, found := s.pins[cid]
	if !found || !validPin(p, now) {
		delete(s.pins, cid)
