	}
	delete(s.pins, cid)
	return true
}

// pinEntry is one live pin in a listing.
type pinEntry struct {
	cid       string
	expiresAt *time.Time
}

// listPins returns the pins in force at now, sorted by cid.
func (s *store) listPins(now time.Time) []pinEntry {
	s.mu.RLock()
	defer s.mu.RUnlock()
