	if rec := post(); rec.Code != http.StatusOK {
		t.Fatalf="local retrieval status = %d", rec.Code)
	}

	_, page := getAuditPage(t, h, "")
	if len(page.Events) != 3 {
		t.Fatalf("events = %d, want 3", len(page.Events))
